# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::ServiceTokenVerifier do
  # "An anonymous or user-delegated request never gets it." Neither a user
  # token, nor a token signed with the public key's text as an HMAC secret,
  # nor one signed with a guessed secret may verify as a company-bound service.
  it "refuses a user token and a token signed with any other secret as a service credential" do
    secret = "service-secret-#{SecureRandom.hex(8)}"
    claims = { typ: "timekeeping_service", sub: "invoice-boundary", company_id: 1,
               operations: ["reservations.commit"], exp: Time.now.to_i + 300, jti: SecureRandom.uuid }
    user_token = mint_token({ sub: 7, company_id: 1, role: "owner" })
    key_confusion = JWT.encode(claims, rsa_key_pair.public_key.to_pem, "HS256")
    guessed = JWT.encode(claims, "guessed", "HS256")
    unsigned = JWT.encode(claims, nil, "none")

    [user_token, key_confusion, guessed, unsigned].each do |token|
      expect { described_class.verify(token, secret:) }.to raise_error(StandardError)
    end
    expect { described_class.verify(JWT.encode(claims, secret, "HS256"), secret: "") }.to raise_error(StandardError)
    expect(described_class.verify(JWT.encode(claims, secret, "HS256"), secret:)).to include("company_id" => 1)
  end
end
